    for x in ast.walk(d):
        if isinstance(x, ast.Call) and isinstance(x.func, ast.Name) and x.func.id in names:
            calls.add(x.func.id)
    graph.setdefault(d.name, set()).update(calls)
cyclic = False
for start in graph:
    seen = set()
    stack = [start]
    while stack:
        cur = stack.pop()
        for nxt in graph.get(cur, ()):
            if nxt == start:
                cyclic = True
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
